insert into problems(lesson_id,sort,title,input,output,solution,explanation,solution2,explanation2) values
(201,87,E'Diamond pattern',E'3',E'  *\n ***\n*****\n ***\n  *',E'n = int(input())\nfor i in list(range(1, n + 1)) + list(range(n - 1, 0, -1)):\n    print('' '' * (n - i) + ''*'' * (2 * i - 1))',E'Row i లో stars 2i-1, spaces n-i; పైకి తర్వాత కిందకి.',E'n = int(input())\nw = 2 * n - 1\nfor i in list(range(1, n + 1)) + list(range(n - 1, 0, -1)):\n    print((''*'' * (2 * i - 1)).center(w).rstrip())',E'str.center తో spaces లెక్కించక్కర్లేదు.'),
(201,88,E'Number to words (0-999)',E'342',E'three hundred forty two',E'n = int(input())\nones = ''zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen''.split()\ntens = ''_ _ twenty thirty forty fifty sixty seventy eighty ninety''.split()\nw = []\nif n >= 100:\n    w += [ones[n // 100], ''hundred'']\n    n %= 100\nif n >= 20:\n    w.append(tens[n // 10])\n    n %= 10\nif n or not w:\n    w.append(ones[n])\nprint('' ''.join(w))',E'వందలు, పదులు, ఒకట్లు వరుసగా వేరు చేసి words list.',E'ones = ''zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen''.split()\ntens = ''_ _ twenty thirty forty fifty sixty seventy eighty ninety''.split()\ndef f(n):\n    if n < 20:\n        return ones[n]\n    if n < 100:\n        return tens[n // 10] + ('' '' + ones[n % 10] if n % 10 else '''')\n    return ones[n // 100] + '' hundred'' + ('' '' + f(n % 100) if n % 100 else '''')\nprint(f(int(input())))',E'Recursion: మిగిలిన భాగానికి అదే function.'),
(201,89,E'Seconds to HH:MM:SS',E'3725',E'01:02:05',E's = int(input())\nh, r = divmod(s, 3600)\nm, sec = divmod(r, 60)\nprint(f''{h:02d}:{m:02d}:{sec:02d}'')',E'divmod తో గంటలు, నిమిషాలు; :02d తో zero padding.',E'import time\nprint(time.strftime(''%H:%M:%S'', time.gmtime(int(input()))))',E'time.gmtime + strftime library తో.'),
(201,90,E'Armstrong numbers up to n',E'500',E'[1, 2, 3, 4, 5, 6, 7, 8, 9, 153, 370, 371, 407]',E'n = int(input())\nres = []\nfor x in range(1, n + 1):\n    d = str(x)\n    if sum(int(c) ** len(d) for c in d) == x:\n        res.append(x)\nprint(res)',E'ప్రతి digit ను (digits సంఖ్య) power కి పెంచి sum.',E'def arm(x):\n    k = len(str(x))\n    t, m = 0, x\n    while m:\n        m, r = divmod(m, 10)\n        t += r ** k\n    return t == x\nprint([x for x in range(1, int(input()) + 1) if arm(x)])',E'Strings లేకుండా divmod తో digits.'),
(201,91,E'Postfix expression',E'3 4 + 2 *',E'14',E'ops = {''+'': lambda a, b: a + b, ''-'': lambda a, b: a - b, ''*'': lambda a, b: a * b, ''/'': lambda a, b: a / b}\nst = []\nfor t in input().split():\n    if t in ops:\n        b = st.pop()\n        a = st.pop()\n        st.append(ops[t](a, b))\n    else:\n        st.append(int(t))\nprint(st[0])',E'Stack: operands push, operator వస్తే రెండు pop చేసి result push.',E'import operator as o\nops = {''+'': o.add, ''-'': o.sub, ''*'': o.mul, ''/'': o.truediv}\nst = []\nfor t in input().split():\n    st.append(ops[t](*[st.pop() for _ in range(2)][::-1]) if t in ops else int(t))\nprint(st[0])',E'operator module; pop order తిప్పి (a, b) గా unpack.'),
(201,92,E'Convert to any base',E'255 16',E'FF',E'n, b = map(int, input().split())\nd = ''0123456789ABCDEF''\ns = ''''\nwhile n:\n    n, r = divmod(n, b)\n    s = d[r] + s\nprint(s or ''0'')',E'divmod: remainder digit, quotient తో కొనసాగింపు.',E'n, b = map(int, input().split())\nd = ''0123456789ABCDEF''\ndef f(n):\n    return '''' if n == 0 else f(n // b) + d[n % b]\nprint(f(n) or ''0'')',E'Recursion: ముందు పైభాగం, తర్వాత చివరి digit.'),
(201,93,E'Magic square check',E'3\n2 7 6\n9 5 1\n4 3 8',E'True',E'n = int(input())\ng = [list(map(int, input().split())) for _ in range(n)]\nt = sum(g[0])\nrows = all(sum(r) == t for r in g)\ncols = all(sum(g[i][j] for i in range(n)) == t for j in range(n))\nd1 = sum(g[i][i] for i in range(n)) == t\nd2 = sum(g[i][n - 1 - i] for i in range(n)) == t\nprint(rows and cols and d1 and d2)',E'rows, columns, రెండు diagonals అన్నీ ఒకే sum.',E'n = int(input())\ng = [list(map(int, input().split())) for _ in range(n)]\nsums = [sum(r) for r in g] + [sum(c) for c in zip(*g)] + [sum(g[i][i] for i in range(n)), sum(g[i][-1 - i] for i in range(n))]\nprint(len(set(sums)) == 1)',E'అన్ని sums ఒక list లో; set size 1 అయితే magic.'),
(201,94,E'Bulls and cows',E'1234 1243',E'2 2',E'a, b = input().split()\nbulls = sum(x == y for x, y in zip(a, b))\ncows = sum(min(a.count(c), b.count(c)) for c in set(a)) - bulls\nprint(bulls, cows)',E'Bulls: ఒకే చోట సమానం; cows: common digits - bulls.',E'from collections import Counter\na, b = input().split()\nbulls = sum(x == y for x, y in zip(a, b))\nprint(bulls, sum((Counter(a) & Counter(b)).values()) - bulls)',E'Counter & = common digits count.'),
(202,95,E'Fibonacci with tuple unpacking',E'10',E'55',E'n = int(input())\na, b = 0, 1\nfor _ in range(n):\n    a, b = b, a + b\nprint(a)',E'a, b = b, a+b ఒకేసారి assign; temp variable అవసరం లేదు.',E'from functools import lru_cache\n@lru_cache(None)\ndef f(n):\n    return n if n < 2 else f(n - 1) + f(n - 2)\nprint(f(int(input())))',E'Recursion + cache (variables కాకుండా function memo).'),
(202,96,E'Shallow vs deep copy',E'[[1,2],[3]]',E'[[99, 2], [3]] [[1, 2], [3]]',E'import ast, copy\na = ast.literal_eval(input())\nb = a.copy()\nc = copy.deepcopy(a)\na[0][0] = 99\nprint(b, c)',E'copy() inner lists share చేస్తుంది, deepcopy పూర్తిగా వేరు.',E'import ast\na = ast.literal_eval(input())\nb = a.copy()\nc = [x[:] for x in a]\na[0][0] = 99\nprint(b, c)',E'ప్రతి inner list ని manually copy చేస్తే deepcopy లాగే.'),
(202,97,E'Palindrome number (no strings)',E'12321',E'True',E'n = int(input())\nm, r = n, 0\nwhile m:\n    r = r * 10 + m % 10\n    m //= 10\nprint(r == n)',E'% 10 తో digit తీసి reverse number నిర్మించాం.',E'n = input()\nprint(n == n[::-1])',E'String reverse తో సులభంగా.'),
(202,98,E'Mutable default argument trap',E'3',E'[1]\n[1]\n[1]',E'def add(x, lst=None):\n    if lst is None:\n        lst = []\n    lst.append(x)\n    return lst\nfor _ in range(int(input())):\n    print(add(1))',E'Default [] ఒక్కసారే create అవుతుంది; None వాడి లోపల కొత్తది చేయాలి.',E'def add(x, lst=()):\n    return list(lst) + [x]\nfor _ in range(int(input())):\n    print(add(1))',E'Immutable default (tuple) + కొత్త list return.'),
(202,99,E'GCD with tuple unpacking',E'48 18',E'6',E'a, b = map(int, input().split())\nwhile b:\n    a, b = b, a % b\nprint(a)',E'Euclid: (a, b) = (b, a % b) ఒకేసారి assign.',E'def g(a, b):\n    return a if b == 0 else g(b, a % b)\nprint(g(*map(int, input().split())))',E'అదే Euclid recursion తో.'),
(202,100,E'Sort three numbers without sort()',E'9 2 5',E'2 5 9',E'a, b, c = map(int, input().split())\nif a > b:\n    a, b = b, a\nif b > c:\n    b, c = c, b\nif a > b:\n    a, b = b, a\nprint(a, b, c)',E'మూడు compare-swap లు.',E'a, b, c = map(int, input().split())\nlo, hi = min(a, b, c), max(a, b, c)\nprint(lo, a + b + c - lo - hi, hi)',E'మధ్యది = మొత్తం - చిన్నది - పెద్దది.'),
(202,101,E'Counter with global vs nonlocal',E'3',E'3',E'count = 0\ndef inc():\n    global count\n    count += 1\nfor _ in range(int(input())):\n    inc()\nprint(count)',E'global keyword తో module-level variable మార్పు.',E'def make():\n    c = 0\n    def inc():\n        nonlocal c\n        c += 1\n        return c\n    return inc\nf = make()\nfor _ in range(int(input())):\n    r = f()\nprint(r)',E'Closure లో nonlocal: global కాలుష్యం లేదు.'),
(202,102,E'Pair up two lists',E'1 2 3\n4 5 6',E'[[1, 4], [2, 5], [3, 6]]',E'a = list(map(int, input().split()))\nb = list(map(int, input().split()))\nprint([list(r) for r in zip(a, b)])',E'zip జతలు చేస్తుంది.',E'a = list(map(int, input().split()))\nb = list(map(int, input().split()))\nprint([[a[i], b[i]] for i in range(len(a))])',E'Index తో manual జతలు.'),
(202,103,E'Star unpacking',E'5 1 2 3 9',E'5 9 6',E'first, *mid, last = map(int, input().split())\nprint(first, last, sum(mid))',E'first, *mid, last: మధ్యవన్నీ list లోకి.',E'a = list(map(int, input().split()))\nprint(a[0], a[-1], sum(a[1:-1]))',E'Indexing + slicing తో అదే.'),
(202,104,E'Reverse integer (32-bit)',E'-123',E'-321',E'n = int(input())\ns = -1 if n < 0 else 1\nr = s * int(str(abs(n))[::-1])\nprint(r if -2 ** 31 <= r < 2 ** 31 else 0)',E'String reverse; 32-bit range దాటితే 0.',E'n = int(input())\ns, m, r = (-1 if n < 0 else 1), abs(n), 0\nwhile m:\n    r = r * 10 + m % 10\n    m //= 10\nr *= s\nprint(r if -2 ** 31 <= r < 2 ** 31 else 0)',E'Arithmetic తో digits తిప్పడం.'),
(203,105,E'Sum numbers in mixed text',E'1 two 3 4.5 five',E'8.5',E'total = 0\nfor t in input().split():\n    try:\n        total += float(t)\n    except ValueError:\n        pass\nprint(total)',E'float() fail అయితే ValueError; skip చేశాం.',E'import re\nprint(sum(float(x) for x in re.findall(r''\\d+(?:\\.\\d+)?'', input())))',E'Regex తో numbers మాత్రమే వెలికితీత.'),
(203,106,E'Digit sum of 100!',E'100',E'648',E'import math\nprint(sum(map(int, str(math.factorial(int(input()))))))',E'Python big ints: 158 digits ఉన్నా overflow లేదు.',E'n = int(input())\nf = 1\nfor i in range(2, n + 1):\n    f *= i\ns = 0\nwhile f:\n    f, r = divmod(f, 10)\n    s += r\nprint(s)',E'Factorial loop తో, digits divmod తో.'),
(203,107,E'Float accumulation error',E'10',E'False True',E'import math\nn = int(input())\nt = 0\nfor _ in range(n):\n    t += 0.1\nprint(t == 1, math.isclose(t, 1))',E'Floats binary లో exact కావు; == బదులు isclose.',E'n = int(input())\nt = 0.0\nfor _ in range(n):\n    t += 0.1\nprint(t == 1, abs(t - 1) < 1e-9)',E'isclose బదులు tolerance (epsilon) తో పోలిక.'),
(203,108,E'Classify tokens: int, float, str',E'10 3.5 abc True -7',E'[''int'', ''float'', ''str'', ''str'', ''int'']',E'out = []\nfor t in input().split():\n    try:\n        int(t)\n        out.append(''int'')\n    except ValueError:\n        try:\n            float(t)\n            out.append(''float'')\n        except ValueError:\n            out.append(''str'')\nprint(out)',E'int ప్రయత్నం, విఫలమైతే float, లేకపోతే str.',E'import re\nout = []\nfor t in input().split():\n    out.append(''int'' if re.fullmatch(r''[+-]?\\d+'', t) else ''float'' if re.fullmatch(r''[+-]?\\d*\\.\\d+'', t) else ''str'')\nprint(out)',E'Regex patterns తో exceptions లేకుండా.'),
(203,109,E'Last 3 digits of 2^n',E'1000',E'376',E'print(pow(2, int(input()), 1000))',E'pow(a, b, mod) modular exponent: పెద్ద number తయారు చేయదు.',E'print(str(2 ** int(input()))[-3:])',E'Big int తయారు చేసి string చివరి 3 digits.'),
(203,110,E'Round half up',E'2.5 3.5 0.5',E'3 4 1',E'print(*[int(float(x) + .5) for x in input().split()])',E'Python round() banker''s rounding; x+0.5 తో half-up.',E'from decimal import Decimal, ROUND_HALF_UP\nprint(*[int(Decimal(x).quantize(Decimal(''1''), rounding=ROUND_HALF_UP)) for x in input().split()])',E'Decimal exact మరియు rounding mode ఎంచుకోవచ్చు.'),
(203,111,E'Count unhashable items',E'[1, [2], (3,), ''a'', {4}]',E'2',E'import ast\ncount = 0\nfor x in ast.literal_eval(input()):\n    try:\n        hash(x)\n    except TypeError:\n        count += 1\nprint(count)',E'hash() fail అయితే unhashable (list, set, dict).',E'import ast\nprint(sum(isinstance(x, (list, dict, set)) for x in ast.literal_eval(input())))',E'Mutable types నేరుగా isinstance తో.'),
(203,112,E'Type frequency',E'[1, ''a'', 2.5, 3, ''b'', True, None]',E'{''int'': 2, ''str'': 2, ''float'': 1, ''bool'': 1, ''NoneType'': 1}',E'import ast\nfrom collections import Counter\nprint(dict(Counter(type(x).__name__ for x in ast.literal_eval(input()))))',E'type(x).__name__ తో Counter.',E'import ast\nd = {}\nfor x in ast.literal_eval(input()):\n    k = type(x).__name__\n    d[k] = d.get(k, 0) + 1\nprint(d)',E'Manual dict count.'),
(203,113,E'Quadratic roots with complex numbers',E'1 2 5',E'(-1+2j) (-1-2j)',E'import cmath\na, b, c = map(int, input().split())\nd = cmath.sqrt(b * b - 4 * a * c)\nprint((-b + d) / (2 * a), (-b - d) / (2 * a))',E'cmath.sqrt negative కి కూడా పనిచేస్తుంది (complex).',E'a, b, c = map(int, input().split())\ndisc = b * b - 4 * a * c\nr = abs(disc) ** .5\nif disc < 0:\n    print(complex(-b, r) / (2 * a), complex(-b, -r) / (2 * a))\nelse:\n    print((-b + r) / (2 * a), (-b - r) / (2 * a))',E'Negative discriminant కి imaginary భాగం manual.'),
(203,114,E'Modify a tuple',E'1 2 3 4\n2 99',E'(1, 2, 99, 4)',E't = tuple(map(int, input().split()))\ni, v = map(int, input().split())\nprint(t[:i] + (v,) + t[i + 1:])',E'Tuple immutable: slices కలిపి కొత్తది.',E't = tuple(map(int, input().split()))\ni, v = map(int, input().split())\nl = list(t)\nl[i] = v\nprint(tuple(l))',E'List గా మార్చి, మార్చి, మళ్ళీ tuple.'),
(204,115,E'Count set bits',E'29',E'4',E'print(bin(int(input())).count(''1''))',E'bin() string లో ''1'' లు count.',E'n = int(input())\nc = 0\nwhile n:\n    n &= n - 1\n    c += 1\nprint(c)',E'n & (n-1) ప్రతిసారి ఒక set bit తొలగిస్తుంది.'),
(204,116,E'Power of two',E'64',E'True',E'n = int(input())\nprint(n > 0 and n & (n - 1) == 0)',E'Power of two లో ఒక్క bit మాత్రమే set.',E'n = int(input())\nprint(n > 0 and bin(n).count(''1'') == 1)',E'Set bits count సరిగ్గా 1.'),
(204,117,E'Single number (others twice)',E'4 1 2 1 2',E'4',E'from functools import reduce\nprint(reduce(lambda a, b: a ^ b, map(int, input().split())))',E'x ^ x = 0, కాబట్టి జతలు రద్దు అవుతాయి. O(1) space.',E'from collections import Counter\nc = Counter(map(int, input().split()))\nprint(next(k for k, v in c.items() if v == 1))',E'Counter తో count 1 ఉన్నది. O(n) space.'),
(204,118,E'Swap without temp',E'5 9',E'9 5',E'a, b = map(int, input().split())\na ^= b\nb ^= a\na ^= b\nprint(a, b)',E'XOR swap: మూడు XORలు.',E'a, b = map(int, input().split())\na = a + b\nb = a - b\na = a - b\nprint(a, b)',E'Sum/difference trick.'),
(204,119,E'Binary without bin()',E'10',E'1010',E'n = int(input())\ns = ''''\nwhile n:\n    s = str(n % 2) + s\n    n //= 2\nprint(s or ''0'')',E'% 2 తో చివరి bit, // 2 తో shift.',E'n = int(input())\nprint(''''.join(str(n >> i & 1) for i in range(n.bit_length() - 1, -1, -1)) or ''0'')',E'Bit shifts తో ఎడమ నుండి కుడికి bits.'),
(204,120,E'Missing number 0..n',E'3 0 1',E'2',E'a = list(map(int, input().split()))\nn = len(a)\nprint(n * (n + 1) // 2 - sum(a))',E'0..n మొత్తం - ఉన్న మొత్తం.',E'a = list(map(int, input().split()))\nx = len(a)\nfor i, v in enumerate(a):\n    x ^= i ^ v\nprint(x)',E'అన్ని indices, values XOR; జతలు రద్దు, missing మిగులుతుంది (overflow భయం లేదు).'),
(204,121,E'Reverse bits (8-bit)',E'13',E'176',E'n = int(input())\nprint(int(format(n, ''08b'')[::-1], 2))',E'8-bit string reverse చేసి int.',E'n = int(input())\nr = 0\nfor _ in range(8):\n    r = (r << 1) | (n & 1)\n    n >>= 1\nprint(r)',E'చివరి bit తీసి r కి కుడివైపు add.'),
(204,122,E'Hamming distance',E'1 4',E'2',E'a, b = map(int, input().split())\nprint(bin(a ^ b).count(''1''))',E'XOR లో 1 లు = తేడా bits.',E'a, b = map(int, input().split())\nx, y = format(a, ''b''), format(b, ''b'')\nw = max(len(x), len(y))\nprint(sum(c != d for c, d in zip(x.zfill(w), y.zfill(w))))',E'Binary strings సమాన పొడవుకి zfill చేసి compare.'),
(204,123,E'Subsets with given sum',E'1 2 3 4\n5',E'2',E'a = list(map(int, input().split()))\nt = int(input())\nn = len(a)\nprint(sum(sum(a[i] for i in range(n) if m >> i & 1) == t for m in range(1 << n)))',E'Bitmask: ప్రతి number ఒక subset.',E'from itertools import combinations\na = list(map(int, input().split()))\nt = int(input())\nprint(sum(sum(c) == t for r in range(len(a) + 1) for c in combinations(a, r)))',E'అన్ని sizes combinations check.'),
(204,124,E'Division truncating toward zero',E'-7 2',E'-3',E'a, b = map(int, input().split())\nq = abs(a) // abs(b)\nprint(q if (a < 0) == (b < 0) else -q)',E'Absolute values తో divide, sign సరిచేయి.',E'a, b = map(int, input().split())\nq = a // b\nprint(q + 1 if q < 0 and q * b != a else q)',E'Floor result negative అయి exact కాకపోతే +1.'),
(205,125,E'Quadratic roots',E'1 -3 2',E'2.0 1.0',E'a, b, c = map(int, input().split())\nd = b * b - 4 * a * c\nif d > 0:\n    print((-b + d ** .5) / (2 * a), (-b - d ** .5) / (2 * a))\nelif d == 0:\n    print(-b / (2 * a))\nelse:\n    print(''No real roots'')',E'Discriminant d చూసి మూడు cases.',E'import math\na, b, c = map(int, input().split())\nd = b * b - 4 * a * c\nprint(''No real roots'' if d < 0 else (-b / (2 * a)) if d == 0 else f''{(-b + math.sqrt(d)) / (2 * a)} {(-b - math.sqrt(d)) / (2 * a)}'')',E'Nested ternary expression.'),
(205,126,E'Triangle type and area',E'3 4 5',E'Right 6.0',E'a, b, c = sorted(map(int, input().split()))\nif a + b <= c:\n    print(''Invalid'')\nelse:\n    t = ''Right'' if a * a + b * b == c * c else ''Acute'' if a * a + b * b > c * c else ''Obtuse''\n    s = (a + b + c) / 2\n    print(t, round((s * (s - a) * (s - b) * (s - c)) ** .5, 2))',E'Sorted చేసి చిన్న రెండు వర్గాల మొత్తాన్ని పెద్దదితో పోల్చాం; Heron''s formula.',E'a, b, c = sorted(map(int, input().split()))\nif a + b <= c:\n    print(''Invalid'')\nelse:\n    diff = a * a + b * b - c * c\n    t = (''Obtuse'', ''Right'', ''Acute'')[(diff >= 0) + (diff > 0)]\n    s = (a + b + c) / 2\n    print(t, round((s * (s - a) * (s - b) * (s - c)) ** .5, 2))',E'bool sum తో tuple index ఎంపిక.'),
(205,127,E'Valid date',E'2023-02-29',E'Invalid',E'y, m, d = map(int, input().split(''-''))\nleap = y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)\ndays = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]\nprint(''Valid'' if 1 <= m <= 12 and 1 <= d <= days[m - 1] else ''Invalid'')',E'Leap year బట్టి Feb రోజులు మారతాయి; month ముందు check.',E'from datetime import date\ny, m, d = map(int, input().split(''-''))\ntry:\n    date(y, m, d)\n    print(''Valid'')\nexcept ValueError:\n    print(''Invalid'')',E'datetime తానే validate చేస్తుంది.'),
(205,128,E'Rock-paper-scissors score (P1 P2)',E'3\nrock scissors\npaper rock\nscissors scissors',E'2 0',E'n = int(input())\np1 = p2 = 0\nfor _ in range(n):\n    a, b = input().split()\n    if a == b:\n        continue\n    if (a, b) in ((''rock'', ''scissors''), (''scissors'', ''paper''), (''paper'', ''rock'')):\n        p1 += 1\n    else:\n        p2 += 1\nprint(p1, p2)',E'Tie skip; గెలిచే జతలు list.',E'beats = {''rock'': ''scissors'', ''scissors'': ''paper'', ''paper'': ''rock''}\nn = int(input())\nrounds = [input().split() for _ in range(n)]\nprint(sum(beats[a] == b for a, b in rounds), sum(beats[b] == a for a, b in rounds))',E'''ఎవరు ఎవరిని ఓడిస్తారు'' dict.'),
(205,129,E'Tax: 0% to 2.5L, 5% to 5L, 10% to 10L, 20% above',E'1200000',E'102500',E'n = int(input())\ntax = 0\nif n > 1000000:\n    tax += (n - 1000000) * 20 // 100\n    n = 1000000\nif n > 500000:\n    tax += (n - 500000) * 10 // 100\n    n = 500000\nif n > 250000:\n    tax += (n - 250000) * 5 // 100\nprint(tax)',E'పై slab నుండి తగ్గిస్తూ ప్రతి slab లో పన్ను.',E'n = int(input())\nslabs = [(250000, 500000, 5), (500000, 1000000, 10), (1000000, float(''inf''), 20)]\nprint(sum((min(n, hi) - lo) * r // 100 for lo, hi, r in slabs if n > lo))',E'Slabs data గా; ప్రతిదానిలో ఉన్న భాగం మీద rate.'),
(205,130,E'Next day of a date',E'2024-02-28',E'2024-02-29',E'y, m, d = map(int, input().split(''-''))\nleap = y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)\ndim = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]\nd += 1\nif d > dim:\n    d, m = 1, m + 1\nif m > 12:\n    m, y = 1, y + 1\nprint(f''{y:04d}-{m:02d}-{d:02d}'')',E'నెల/సంవత్సరం చివరన rollover conditions.',E'from datetime import date, timedelta\nprint(date.fromisoformat(input()) + timedelta(1))',E'timedelta తో నేరుగా.'),
(205,131,E'Perfect, abundant or deficient',E'28',E'Perfect',E'n = int(input())\ns = sum(i for i in range(1, n) if n % i == 0)\nif s == n:\n    print(''Perfect'')\nelif s > n:\n    print(''Abundant'')\nelse:\n    print(''Deficient'')',E'Proper divisors మొత్తం n తో పోల్చాం.',E'n = int(input())\ns = sum(i for i in range(1, n // 2 + 1) if n % i == 0)\nprint([''Deficient'', ''Perfect'', ''Abundant''][(s >= n) + (s > n)])',E'n/2 వరకే divisors; bool sum index.');
